
function labInside(p,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
function labNormalize(poly){const x=Math.min(...poly.map(p=>p[0])),y=Math.min(...poly.map(p=>p[1]));return poly.map(p=>[p[0]-x,p[1]-y]);}
LAB_ENGINES.mosaic={
 init(c,seed){const d={selected:0,placed:[],undo:[]};if(c.variant==='tangram'){d.solution=[[[0,0],[4,0],[2,2]],[[0,0],[2,2],[0,4]],[[4,4],[2,4],[4,2]],[[4,0],[4,2],[3,1]],[[2,2],[3,3],[1,3]],[[2,2],[3,1],[4,2],[3,3]],[[0,4],[1,3],[3,3],[2,4]]];d.pieces=d.solution.map(poly=>{let p=labNormalize(poly);for(let i=0;i<seed%4;i++)p=labNormalize(p.map(([x,y])=>[-y,x]));return p;});d.occupied=[];}else{d.coords=[];for(let r=-2;r<=2;r++)for(let q=Math.max(-2,-r-2);q<=Math.min(2,-r+2);q++)d.coords.push([q,r]);d.pieces=[3,4,5,4,3].map(n=>Array.from({length:n},(_,i)=>[i,0]));d.solution=[0,3,7,12,16];}return d;},
 render(d,c){const tangram=c.variant==='tangram',poly=d.pieces[d.selected]||[],preview=tangram?'<svg viewBox="-0.2 -0.2 4.4 4.4" width="85" height="70"><polygon points="'+poly.map(p=>p.join(',')).join(' ')+'" fill="'+LAB_COLORS[d.selected%6]+'"/></svg>':'<p>Selected piece: '+poly.length+' hexagons</p>';return '<p>'+(tangram?'Fit all seven tangram pieces inside the square. Choose a piece, rotate it, then tap its top-left grid anchor.':'Fit five hexagon strips into the honeycomb. Choose a piece, rotate it, then tap its starting hexagon.')+'</p><div class="lab-options">'+d.pieces.map((p,i)=>labButton('piece',i+1,i,d.placed.some(x=>x.id===i))).join('')+'</div>'+preview+(tangram?'<svg class="lab-mosaic" viewBox="-0.3 -0.3 4.6 4.6"><rect width="4" height="4" fill="#eae5fa" stroke="#8a72aa" stroke-width=".04"/>'+d.placed.map(p=>'<polygon points="'+p.poly.map(p=>p.join(',')).join(' ')+'" fill="'+LAB_COLORS[p.id%6]+'" stroke="white" stroke-width=".02"/>').join('')+Array.from({length:25},(_,i)=>'<circle data-mosaic-anchor="'+i+'" cx="'+(i%5)+'" cy="'+Math.floor(i/5)+'" r=".12" fill="#6a5683" tabindex="0" role="button" aria-label="Anchor '+i+'"/>').join('')+'</svg>':'<svg class="lab-mosaic" viewBox="-130 -120 260 240">'+d.coords.map(([q,r],i)=>{const x=(q+r/2)*42,y=r*36,id=d.placed.find(p=>p.cells.includes(i))?.id;return '<g data-mosaic-anchor="'+i+'" tabindex="0" role="button" aria-label="Hexagon '+i+'"><polygon points="'+Array.from({length:6},(_,k)=>{const a=(k*60-30)*Math.PI/180;return (x+23*Math.cos(a))+','+(y+23*Math.sin(a));}).join(' ')+'" fill="'+(id!==undefined?LAB_COLORS[id]:'#eae5fa')+'" stroke="#9879bf" stroke-width="2"/><text x="'+x+'" y="'+(y+5)+'" text-anchor="middle" font-size="12">'+(i+1)+'</text></g>';}).join('')+'</svg>')+labButton('rotate','Rotate')+labButton('undo','Undo placement');},
 action(d,a,n,c){if(a==='piece'&&!d.placed.some(x=>x.id===n)){d.selected=n;return;}if(a==='undo'){d.placed.pop();return;}if(a==='rotate'){d.pieces[d.selected]=c.variant==='tangram'?labNormalize(d.pieces[d.selected].map(([x,y])=>[-y,x])):d.pieces[d.selected].map(([q,r])=>[-r,q+r]);return;}if(a!=='anchor'||d.placed.some(p=>p.id===d.selected))return;const piece=d.pieces[d.selected];if(c.variant==='tangram'){const poly=piece.map(([x,y])=>[x+n%5,y+Math.floor(n/5)]);if(poly.some(([x,y])=>x<0||y<0||x>4||y>4)){labMiss('Keep every corner inside the square.');return;}const cells=[];for(let y=0;y<4;y++)for(let x=0;x<4;x++)[[.5,1/6],[5/6,.5],[.5,5/6],[1/6,.5]].forEach(([dx,dy],k)=>{if(labInside([x+dx,y+dy],poly))cells.push((y*4+x)*4+k);});if(d.placed.some(p=>p.cells.some(i=>cells.includes(i)))){labMiss('The pieces must not overlap.');return;}d.placed.push({id:d.selected,poly,cells});}else{const [q,r]=d.coords[n],cells=piece.map(([x,y])=>d.coords.findIndex(p=>p[0]===q+x&&p[1]===r+y));if(cells.some(i=>i<0)||d.placed.some(p=>p.cells.some(i=>cells.includes(i)))){labMiss('Find a clear space inside the honeycomb.');return;}d.placed.push({id:d.selected,cells});}game.session.moves++;if(d.placed.length===d.pieces.length)labWin('A complete mosaic!');else d.selected=d.pieces.findIndex((_,i)=>!d.placed.some(p=>p.id===i));},
 bind(){document.querySelectorAll('[data-mosaic-anchor]').forEach(el=>{const go=()=>labHandle({dataset:{modeAction:'lab-anchor',value:el.dataset.mosaicAnchor}});el.onclick=go;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}};});}
};
